import json, os, re, subprocess, tempfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MOCK="\nlet signed=false;\nlet sample={id:1,first_name:'Jane',last_name:'Doe',company:'Feuji',email:'jane@example.com',phone:'+919876543210',country_code:'+91',country_region:'IN',created_at:1700000000,last_login:1700000010,active_sessions:1};\nlet entries=[sample];\nwindow.fetch=async(path,options={})=>{\n let payload={},ok=true;\n if(path==='/api/auth/countries')payload=countryData;\n else if(path==='/api/admin/login'){signed=true;payload={message:'Signed in.'};}\n else if(!signed){ok=false;payload={detail:'Sign in as administrator to continue.'};}\n else if(path==='/api/admin/me')payload={admin:true};\n else if(path==='/api/admin/logout'){signed=false;}\n else if(path==='/api/admin/users'&&options.method==='POST'){const data=JSON.parse(options.body);entries.push({...sample,...data,id:2,phone:data.country_code+data.phone});}\n else if(path==='/api/admin/users/1'&&options.method==='PUT'){entries[0]={...entries[0],...JSON.parse(options.body)};}\n else if(path==='/api/admin/users/1'&&options.method==='DELETE'){entries=entries.filter(u=>u.id!==1);}\n else if(path==='/api/admin/users')payload=entries;\n else if(path==='/api/admin/logs')payload=[{email:sample.email,login_at:1700000010,logout_at:null,expires_at:1700086410,status:'Active'}];\n return {ok,status:ok?200:401,json:async()=>payload};\n};\n"
TESTS='\n(async()=>{\nconst assert=(value,message)=>{if(!value)throw Error(message)},tick=()=>new Promise(resolve=>setTimeout(resolve,20));\nawait tick();assert(!document.querySelector(\'#admin-login\').hidden,\'Admin password gate visible\');\nconst login=document.querySelector(\'#admin-login-form\');login.elements.password.value=\'admin\';await login.onsubmit({preventDefault(){},currentTarget:login});\nassert(!document.querySelector(\'#admin-workspace\').hidden,\'Admin opens\');assert(document.querySelector(\'#users-body\').textContent.includes(\'jane@example.com\'),\'User listed\');\nentries.push({...sample,id:3,first_name:\'Alice\',email:\'alice@example.com\',created_at:null,active_sessions:10});await document.querySelector(\'#refresh\').onclick();\nconst sortButton=(table,key)=>document.querySelector(`[data-table="${table}"][data-sort="${key}"]`);\nsortButton(\'users\',\'name\').click();assert(document.querySelector(\'#users-body tr\').textContent.includes(\'Alice\'),\'User ascending sort\');assert(sortButton(\'users\',\'name\').closest(\'th\').getAttribute(\'aria-sort\')===\'ascending\',\'Ascending indicator\');\nsortButton(\'users\',\'name\').click();assert(document.querySelector(\'#users-body tr\').textContent.includes(\'Jane\'),\'User descending sort\');\nsortButton(\'users\',\'active_sessions\').click();assert(document.querySelector(\'#users-body tr\').textContent.includes(\'Jane\'),\'Numeric session sorting\');sortButton(\'users\',\'active_sessions\').click();assert(document.querySelector(\'#users-body tr\').textContent.includes(\'Alice\'),\'Numeric descending sort\');\nsortButton(\'users\',\'created_at\').click();assert(document.querySelector(\'#users-body tr\').textContent.includes(\'Jane\'),\'Missing dates last\');\nentries=entries.filter(u=>u.id!==3);await document.querySelector(\'#refresh\').onclick();\ndocument.querySelector(\'[data-section=logs]\').click();assert(!document.querySelector(\'#logs-section\').hidden,\'Logs section\');assert(document.querySelector(\'#logs-body\').textContent.includes(\'IST\'),\'Log timestamps\');\nsortButton(\'logs\',\'login_at\').click();assert(sortButton(\'logs\',\'login_at\').closest(\'th\').getAttribute(\'aria-sort\')===\'ascending\',\'Log ascending sort\');sortButton(\'logs\',\'login_at\').click();assert(sortButton(\'logs\',\'login_at\').closest(\'th\').getAttribute(\'aria-sort\')===\'descending\',\'Log descending sort\');\ndocument.querySelector(\'[data-section=users]\').click();document.querySelector(\'[data-edit="1"]\').click();\nconst form=document.querySelector(\'#user-form\');assert(form.elements.phone.value===\'9876543210\',\'Edit phone split\');assert(!form.elements.password.required,\'Password optional for edit\');form.elements.first_name.value=\'Updated\';await form.onsubmit({preventDefault(){}});assert(document.querySelector(\'#users-body\').textContent.includes(\'Updated\'),\'Edit saved\');\ndocument.querySelector(\'#create-user\').click();assert(form.elements.password.required,\'Password required on creation\');for(const [key,value] of Object.entries({first_name:\'New\',last_name:\'User\',company:\'Feuji\',email:\'new@example.com\',phone:\'9876543210\',password:\'new-password123\'}))form.elements[key].value=value;await form.onsubmit({preventDefault(){}});assert(document.querySelector(\'#users-body\').textContent.includes(\'new@example.com\'),\'Create saved\');\ndocument.querySelector(\'[data-delete="1"]\').click();assert(document.querySelector(\'#delete-dialog\').open,\'Delete confirmation\');await document.querySelector(\'#confirm-delete\').onclick({currentTarget:document.querySelector(\'#confirm-delete\')});assert(!document.querySelector(\'#users-body\').textContent.includes(\'jane@example.com\'),\'Delete saved\');\nawait document.querySelector(\'#admin-logout\').onclick();assert(document.querySelector(\'#admin-workspace\').hidden,\'Sign-out locks console\');\ndocument.body.innerHTML=\'<pre id="smoke-result">PASS: admin sign-in, navigation, create, edit, delete, logs, and sign-out</pre>\';\n})().catch(error=>{document.body.innerHTML=\'<pre id="smoke-result"></pre>\';document.querySelector(\'pre\').textContent=\'FAIL: \'+error.stack;});\n'
def main():
    chrome = Path(os.environ.get('PROGRAMFILES', 'C:/Program Files')) / 'Google/Chrome/Application/chrome.exe'
    if not chrome.exists():
        raise SystemExit('Chrome not installed')
    html = (ROOT / 'frontend/admin.html').read_text(encoding='utf-8')
    js = (ROOT / 'frontend/admin.js').read_text(encoding='utf-8').replace('\ninitialize();', '\n')
    html = re.sub(r'<link rel="stylesheet"[^>]*>', lambda _: '<style>'+(ROOT/'frontend/admin.css').read_text(encoding='utf-8')+'</style>',html)
    countries = (ROOT/'frontend/country-codes.json').read_text(encoding='utf-8')
    mock = "window.countryData="+countries+";"+MOCK
    html = re.sub(r'<script src="[^\"]+" defer></script>', '', html)
    html = html.replace('</body>', '<script>'+mock+'\n'+js+'\n'+TESTS+'</script></body>')
    with tempfile.TemporaryDirectory(prefix='dq-smoke-') as tmp:
        page = Path(tmp)/'smoke.html'; page.write_text(html, encoding='utf-8')
        result = subprocess.run([str(chrome),'--headless','--disable-gpu','--no-first-run','--no-default-browser-check', '--user-data-dir='+str(Path(tmp)/'profile'),'--virtual-time-budget=3000','--dump-dom',page.as_uri()],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=45)
        match = re.search(r'<pre id="smoke-result">(.*?)</pre>',result.stdout,re.S)
        if not match: raise SystemExit('Browser did not complete checks: '+result.stderr[-1000:])
        print(match.group(1))
        if not match.group(1).startswith('PASS'): raise SystemExit(1)

if __name__ == '__main__':
    main()
